-- Explicit LOCAL allocation policy, not native rollMax semantics.
-- Caps count successful bundles per recipient/fight/item by default, never quantities.
-- Native aLO.cpL mappings from accredited item inventory export, SHA256 below.
CREATE TABLE native_drop_item_rarities (
 reference integer PRIMARY KEY CHECK(reference>0),
 rarity_code smallint NOT NULL CHECK(rarity_code>=0),
 source_sha256 text NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$')
);
CREATE TABLE fight_drop_allocation_policies (
 fight_id integer PRIMARY KEY REFERENCES combat_fights(id),
 policy jsonb NOT NULL CHECK(jsonb_typeof(policy)='object')
);
CREATE TABLE fight_drop_allocations (
 fight_id integer NOT NULL,
 character_id bigint NOT NULL,
 snapshot jsonb NOT NULL CHECK(jsonb_typeof(snapshot)='object'),
 snapshot_sha256 text NOT NULL CHECK(snapshot_sha256 ~ '^[0-9a-f]{64}$'),
 PRIMARY KEY(fight_id,character_id),
 FOREIGN KEY(fight_id,character_id) REFERENCES combat_fight_participants(fight_id,character_id)
);
CREATE FUNCTION prevent_drop_allocation_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Drop allocation receipts are immutable'; END $$;
CREATE TRIGGER immutable_native_drop_item_rarities BEFORE UPDATE OR DELETE ON native_drop_item_rarities
 FOR EACH ROW EXECUTE FUNCTION prevent_drop_allocation_mutation();
CREATE TRIGGER immutable_drop_allocation_policy BEFORE UPDATE OR DELETE ON fight_drop_allocation_policies
 FOR EACH ROW EXECUTE FUNCTION prevent_drop_allocation_mutation();
CREATE TRIGGER immutable_drop_allocation_receipt BEFORE UPDATE OR DELETE ON fight_drop_allocations
 FOR EACH ROW EXECUTE FUNCTION prevent_drop_allocation_mutation();
